import { useMap } from "../../contexts/MapContextProvider";
import PropTypes from "prop-types";
import Dialog from "@mui/material/Dialog";
import DialogTitle from "@mui/material/DialogTitle";
import DialogContent from "@mui/material/DialogContent";
import IconButton from "@mui/material/IconButton";
import CloseIcon from "@mui/icons-material/Close";
import Typography from "@mui/material/Typography";
import { Box, Grid, TextField } from "@mui/material";
import LocationOnIcon from "@mui/icons-material/LocationOn";
import MapIcon from "@mui/icons-material/Map";
import PlacesAutocomplete from "../common/PlacesAutocomplete";

const BootstrapDialogTitle = (props) => {
  const { children, onClose, ...other } = props;

  return (
    <DialogTitle sx={{ m: 0, p: 2 }} {...other}>
      {children}
      {onClose ? (
        <IconButton
          aria-label="close"
          onClick={onClose}
          sx={{
            position: "absolute",
            right: 8,
            top: 8,
            color: (theme) => theme.palette.grey[500],
          }}
        >
          <CloseIcon />
        </IconButton>
      ) : null}
    </DialogTitle>
  );
};

BootstrapDialogTitle.propTypes = {
  children: PropTypes.node,
  onClose: PropTypes.func.isRequired,
};

function LocationSearch() {
  const { openSearch, handleCloseSearch, submitMyLocation } = useMap();

  return (
    <div>
      <Dialog
        onClose={handleCloseSearch}
        aria-labelledby="customized-dialog-title"
        open={openSearch}
        sx={{
          "& .MuiDialog-paper": {
            py: "10px",
            px: "10px",
          },
        }}
      >
        <BootstrapDialogTitle
          id="customized-dialog-title"
          onClose={handleCloseSearch}
          sx={{ pl: "20px" }}
        >
          <Box sx={{ display: "flex", alignItems: "center" }}>
            <MapIcon color="error" sx={{ fontSize: "40px" }} />
            <Typography
              variant="h5"
              sx={{ ml: "10px", fontWeight: 600 }}
              style={{ color: "#545454" }}
            >
              Search restaurants by location
            </Typography>
          </Box>
        </BootstrapDialogTitle>
        <DialogContent>
          <Grid
            container
            sx={{
              width: "500px",
              mt: "15px",
              mb: "20px",
              
            }}
          >
            <Grid item xs={10}>
              {/* <TextField
                fullWidth
                label="Enter preferred location"
                onKeyPress={(e) => {
                  if (e.key === "Enter") {
                    handleSubmitSearch(e.target.value);
                  }
                }}
              ></TextField> */}
              <PlacesAutocomplete />
            </Grid>
            <Grid
              item
              xs={2}
              style={{
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
              }}
            >
              <a onClick={() => submitMyLocation()}>
                <LocationOnIcon color="error" style={{ fontSize: "40px" }} />
              </a>
            </Grid>
          </Grid>
        </DialogContent>
      </Dialog>
    </div>
  );
}

export default LocationSearch;
